(4828472, 699570, 56275, '<td valign="top">Not exactly sure what I''m looking at.. while the DOF and lighting is nice, it leaves me with a puzzled look.</td>', 'Not exactly sure what I''m looking at.. while the DOF and lighting is nice, it leaves me with a puzzled look.', '2008-07-16 10:42:11.000000', NULL, 1),
(4828478, 698689, 43463, '<td valign="top">Superb capture of the grilled shrimp and tuna on the grill. Lighting is excellent and the focus shows us all the yummy details. Love how you composed this to show us the food on the diagonal so that we can see the flames of the grill in the lower left half. It just adds another pleasing element to the composition such that we not only feast our eyes on the meal but we can almost feel the heat &amp; smell the grilling spices. Good work on this one 9</td>', 'Superb capture of the grilled shrimp and tuna on the grill. Lighting is excellent and the focus shows us all the yummy details. Love how you composed this to show us the food on the diagonal so that we can see the flames of the grill in the lower left half. It just adds another pleasing element to the composition such that we not only feast our eyes on the meal but we can almost feel the heat & smell the grilling spices. Good work on this one 9', '2008-07-16 10:43:32.000000', NULL, 1),
(4828482, 699687, 56275, '<td valign="top">Not a very appetizing picture.. Lighting seems harsh, background is dark..</td>', 'Not a very appetizing picture.. Lighting seems harsh, background is dark..', '2008-07-16 10:44:29.000000', NULL, 1),
(4828485, 699685, 56275, '<td valign="top">Good idea using the spoon. Better lighting, or adjusting the contrast would help give more definition to the food.</td>', 'Good idea using the spoon. Better lighting, or adjusting the contrast would help give more definition to the food.', '2008-07-16 10:45:32.000000', NULL, 1),
