(4833757, 699555, 57570, '<td valign="top">hmmm....yummmy... bumping u up</td>', 'hmmm....yummmy... bumping u up', '2008-07-19 11:44:49.000000', NULL, 1),
(4833758, 699510, 57570, '<td valign="top">you have styled the food nice but the colors of the place distracts the eye a bit...otherwise a very nice shot.</td>', 'you have styled the food nice but the colors of the place distracts the eye a bit...otherwise a very nice shot.', '2008-07-19 11:45:45.000000', NULL, 1),
(4833759, 697337, 57570, '<td valign="top">nice bright and clear</td>', 'nice bright and clear', '2008-07-19 11:45:56.000000', NULL, 1),
(4833760, 699176, 94876, '<td valign="top">Interesting title considering all the other ingredients here ;)  There''s not much going on for me here.  No focal point.  Too busy. Poor lighting.</td>', 'Interesting title considering all the other ingredients here ;)  There''s not much going on for me here.  No focal point.  Too busy. Poor lighting.', '2008-07-19 11:46:22.000000', NULL, 1),
(4833761, 699289, 57570, '<td valign="top">i really like the arrangement and lighting on this shot...i just wish i was a bit more sharper.</td>', 'i really like the arrangement and lighting on this shot...i just wish i was a bit more sharper.', '2008-07-19 11:46:53.000000', NULL, 1),
(4833762, 699498, 57570, '<td valign="top">nice lighting.</td>', 'nice lighting.', '2008-07-19 11:47:06.000000', NULL, 1),
(4833763, 698813, 57570, '<td valign="top">colorful!</td>', 'colorful!', '2008-07-19 11:47:41.000000', NULL, 1),
(4833764, 698611, 57570, '<td valign="top">good composition, arrangement and lighting...the text on the plate doesn''t go well with the shot.</td>', 'good composition, arrangement and lighting...the text on the plate doesn''t go well with the shot.', '2008-07-19 11:48:55.000000', NULL, 1),
(4833765, 699478, 94876, '<td valign="top">compositionally, theres alot going on here.  I''m a believer that wet produce can dress up an image, but I think the wet garlic stands out too much, and maybe the wet onion as well.  I don''t really like the DOF here, and the comp seems underexposed.</td>', 'compositionally, theres alot going on here.  I''m a believer that wet produce can dress up an image, but I think the wet garlic stands out too much, and maybe the wet onion as well.  I don''t really like the DOF here, and the comp seems underexposed.', '2008-07-19 11:48:58.000000', NULL, 1),
(4833767, 699601, 94876, '<td valign="top">Love the idea, framing and the wash.  Kudos to your model, he seems to fit the role well.  Great expression on his face, and the hand in the mouth is great!</td>', 'Love the idea, framing and the wash.  Kudos to your model, he seems to fit the role well.  Great expression on his face, and the hand in the mouth is great!', '2008-07-19 11:50:12.000000', NULL, 1),
(4833769, 699394, 57570, '<td valign="top">greater part of the image should have been in focus...good try</td>', 'greater part of the image should have been in focus...good try', '2008-07-19 11:51:11.000000', NULL, 1),
(4833771, 698110, 57570, '<td valign="top">i wish the image was sharper an brighter</td>', 'i wish the image was sharper an brighter', '2008-07-19 11:52:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4833772, 698353, 94876, '<td valign="top">I think the framing is excellent.  the blue plate was a great choice.  Well lit.  Looks delicious.</td>', 'I think the framing is excellent.  the blue plate was a great choice.  Well lit.  Looks delicious.', '2008-07-19 11:52:13.000000', NULL, 1),
(4833777, 699631, 57570, '<td valign="top">desserts are hard to shoot..but you have done a pretty good shot. I have just 2 suggestions to make....more of the dessert should be in the frame (too much white space on top) and slightly more light on the cherries.</td>', 'desserts are hard to shoot..but you have done a pretty good shot. I have just 2 suggestions to make....more of the dessert should be in the frame (too much white space on top) and slightly more light on the cherries.', '2008-07-19 11:54:34.000000', NULL, 1),
(4833779, 697383, 94876, '<td valign="top">Great lighting, interesting framing.  I personally feel that the blur is overused here.  really takes away from the comp overall.</td>', 'Great lighting, interesting framing.  I personally feel that the blur is overused here.  really takes away from the comp overall.', '2008-07-19 11:59:46.000000', NULL, 1),
(4833784, 699691, 94876, '<td valign="top">I love all sorts of things about this composition. From the lighting right down to the condiments bleeding out the side and the choice of bun.  All these elements really strengthen the image..  The DOF works well for me.  Love the strawberry shortcake in the background.  It almost gives of a feeling of jealousy towards the hamburger.  Great shot.</td>', 'I love all sorts of things about this composition. From the lighting right down to the condiments bleeding out the side and the choice of bun.  All these elements really strengthen the image..  The DOF works well for me.  Love the strawberry shortcake in the background.  It almost gives of a feeling of jealousy towards the hamburger.  Great shot.', '2008-07-19 12:13:23.000000', NULL, 1),
(4833785, 698082, 94876, '<td valign="top">This composition doesn''t really appeal to me, personally.  The plate doesn''t compliment the subject, IMO.  the background shadow and that wet spot should have been cleaned up.  I could do without the spoon.<br/> <br/>I do like the exposure and the lighting.</td>', 'This composition doesn''t really appeal to me, personally.  The plate doesn''t compliment the subject, IMO.  the background shadow and that wet spot should have been cleaned up.  I could do without the spoon. I do like the exposure and the lighting.', '2008-07-19 12:15:45.000000', NULL, 1),
(4833793, 699021, 94876, '<td valign="top">This comp is interesting in so many ways.  It''s very strong visually.  It''s well framed.  The lighting and exposure are spot on.  The details of the side of the dish are subtle, but add real depth to the image.  The tones in this comp are fantastic.  Love the dual toned marshmallows.  Great subject matter. Awesome DOF.  The only things I really don''t favor (and they''re minor) are the border, and the fact that the chocolate sauce isn''t quite smooth and drippy looking enough for me.  But, like I said, are these complaints?  Hell no, this is a great shot.</td>', 'This comp is interesting in so many ways.  It''s very strong visually.  It''s well framed.  The lighting and exposure are spot on.  The details of the side of the dish are subtle, but add real depth to the image.  The tones in this comp are fantastic.  Love the dual toned marshmallows.  Great subject matter. Awesome DOF.  The only things I really don''t favor (and they''re minor) are the border, and the fact that the chocolate sauce isn''t quite smooth and drippy looking enough for me.  But, like I said, are these complaints?  Hell no, this is a great shot.', '2008-07-19 12:23:05.000000', NULL, 1),
(4833797, 699291, 94876, '<td valign="top">DOF feels off.  The framing and angle of the shot leave something to be desired IMO.  There''s no real focal point.  That pizza looks friggin'' delish, though.  I''d probably want to shoot it as well.</td>', 'DOF feels off.  The framing and angle of the shot leave something to be desired IMO.  There''s no real focal point.  That pizza looks friggin'' delish, though.  I''d probably want to shoot it as well.', '2008-07-19 12:27:04.000000', NULL, 1),
(4833802, 699422, 94876, '<td valign="top">Well, this is my first "10".  I can''t add anything to what this composition doesn''t already tell the viewer.  It''s brilliant in every way.  DOF, lighting, the tonal qualities stun me.  I love it.  Well done.</td>', 'Well, this is my first "10".  I can''t add anything to what this composition doesn''t already tell the viewer.  It''s brilliant in every way.  DOF, lighting, the tonal qualities stun me.  I love it.  Well done.', '2008-07-19 12:29:21.000000', NULL, 1),
(4833803, 699638, 94876, '<td valign="top">It''s a rather bland composition, IMO.  There''s not much here to attract the eye, or cause a viewer to go hmm.</td>', 'It''s a rather bland composition, IMO.  There''s not much here to attract the eye, or cause a viewer to go hmm.', '2008-07-19 12:30:20.000000', NULL, 1),
(4833814, 699678, 94876, '<td valign="top">There are elements of this comp that I like alot, including the lighting and the framing.  The subject, however seems to me to be a little out of focus, though.  Not a bad effort, though.</td>', 'There are elements of this comp that I like alot, including the lighting and the framing.  The subject, however seems to me to be a little out of focus, though.  Not a bad effort, though.', '2008-07-19 12:47:05.000000', NULL, 1),
(4833818, 699410, 94876, '<td valign="top">Nice DOF.  Too many of the images in this competition were just too busy.  I like this comp for it''s simplicity and elegance.  It''s well lit, and the background tones don''t dominate, but rather compliment the subject well.  Well done.</td>', 'Nice DOF.  Too many of the images in this competition were just too busy.  I like this comp for it''s simplicity and elegance.  It''s well lit, and the background tones don''t dominate, but rather compliment the subject well.  Well done.', '2008-07-19 12:49:45.000000', NULL, 1),
(4833824, 699467, 94876, '<td valign="top">I like this composition.  The dynamic lighting creates an atmosphere, illuminating the subject of the photo and giving it a great focal point, at the same time, casting some wicked shadows.  It almost tells one part of a story, and begs to be told the rest.  Great effect.  The wooden spoon that has been dipped in the sauce really helps this backstory.  As if someone had been cooking and had to walk away.  This is definitely a "picture is worth 1000 words" moment for me.  Well done.</td>', 'I like this composition.  The dynamic lighting creates an atmosphere, illuminating the subject of the photo and giving it a great focal point, at the same time, casting some wicked shadows.  It almost tells one part of a story, and begs to be told the rest.  Great effect.  The wooden spoon that has been dipped in the sauce really helps this backstory.  As if someone had been cooking and had to walk away.  This is definitely a "picture is worth 1000 words" moment for me.  Well done.', '2008-07-19 12:53:35.000000', NULL, 1),
(4833827, 699646, 94876, '<td valign="top">everything about this comp is fantastic, except the border, IMO.  Well done.  Visually stunning.  Takes my breath away.  I''d love to see the statistics on young vegetables we lose to lung cancer.  I''m sure the numbers are staggering.  Well done!</td>', 'everything about this comp is fantastic, except the border, IMO.  Well done.  Visually stunning.  Takes my breath away.  I''d love to see the statistics on young vegetables we lose to lung cancer.  I''m sure the numbers are staggering.  Well done!', '2008-07-19 12:55:25.000000', NULL, 1),
(4833828, 699614, 94876, '<td valign="top">great angle, DOF and framing!  Well done.  This comp speaks volumes of your talent and vision.</td>', 'great angle, DOF and framing!  Well done.  This comp speaks volumes of your talent and vision.', '2008-07-19 12:56:03.000000', NULL, 1),
(4833870, 698262, 61818, '<td valign="top">Very nice.</td>', 'Very nice.', '2008-07-19 13:34:07.000000', NULL, 1),
(4834036, 699665, 43774, '<td valign="top">At first glance I thought this was a drink, but then I realized it was jello and cream. I love the colours and I like how the two things sticking out of the glass look like neon (what are they anyway?).</td>', 'At first glance I thought this was a drink, but then I realized it was jello and cream. I love the colours and I like how the two things sticking out of the glass look like neon (what are they anyway?).', '2008-07-19 16:03:48.000000', NULL, 1),
(4834037, 698845, 43774, '<td valign="top">Very clear, good DOF, great colours, one of my top picks. I''ve never seen mozzarella in little balls like that before.</td>', 'Very clear, good DOF, great colours, one of my top picks. I''ve never seen mozzarella in little balls like that before.', '2008-07-19 16:04:31.000000', NULL, 1),
(4834038, 699478, 43774, '<td valign="top">Very nice setup. I''d score this a point higher if it were a bit brighter. As it is you get an 8.</td>', 'Very nice setup. I''d score this a point higher if it were a bit brighter. As it is you get an 8.', '2008-07-19 16:05:16.000000', NULL, 1),
