(4846739, 699433, 30982, '<td valign="top">These look incredibly good.  I''m SO glad you did indeed post the recipe!  Where do you get pastry cutters?  I''ve been trying to find one...  Oh, and the picture rocks.  Way freakin'' underrated and I have no idea why.  Very good detail, great light, and really, they look delicious!</td>', 'These look incredibly good.  I''m SO glad you did indeed post the recipe!  Where do you get pastry cutters?  I''ve been trying to find one...  Oh, and the picture rocks.  Way freakin'' underrated and I have no idea why.  Very good detail, great light, and really, they look delicious!', '2008-07-27 17:12:51.000000', NULL, 0),
(4846752, 699248, 30982, '<td valign="top">This looks like it would be good for you AND taste good - which somehow seems next to impossible.  Except I''ve been to your house, so I do know that it''s possible!  Lovely salad, lovely shot of said salad.  But I have to ask, do you discard just the crushed garlic, or the red wine vinegar and 30 minutes as well?  (Ducking and running...)</td>', 'This looks like it would be good for you AND taste good - which somehow seems next to impossible.  Except I''ve been to your house, so I do know that it''s possible!  Lovely salad, lovely shot of said salad.  But I have to ask, do you discard just the crushed garlic, or the red wine vinegar and 30 minutes as well?  (Ducking and running...)', '2008-07-27 17:24:58.000000', NULL, 0),
(4846754, 699567, 30982, '<td valign="top">That there is a heart attack waiting to happen.  And I can nearly smell how good it is from your description, too.</td>', 'That there is a heart attack waiting to happen.  And I can nearly smell how good it is from your description, too.', '2008-07-27 17:26:06.000000', NULL, 0),
(4846757, 699704, 30982, '<td valign="top">LOL!!  Are you trying to outdo me with the description part of the challenges?  Love the part about "this is a good thing" and really LOVE the last line.  IT''s a bit too symmetrical for me, but it is very colorful and patriotic!  And my mother has done things with that nasty rhubarb stuff too.  I never did like it.</td>', 'LOL!!  Are you trying to outdo me with the description part of the challenges?  Love the part about "this is a good thing" and really LOVE the last line.  IT''s a bit too symmetrical for me, but it is very colorful and patriotic!  And my mother has done things with that nasty rhubarb stuff too.  I never did like it.', '2008-07-27 17:29:01.000000', NULL, 0),
(4846760, 699067, 30982, '<td valign="top">I really like how you set out the spices in front to show what went into it - very nice touch for a recipe challenge.  They look very good, too!  (I discovered something called McCormicks Roast Rub, which is a whole lot easier given that I don''t cook, don''t have a mortar and pestle, and would completely forget I had ribs in bags waiting to be cooked after I rubbed them... Anyway, the pre-produced rub probably isn''t nearly as good but works pretty well on tri-tip!)</td>', 'I really like how you set out the spices in front to show what went into it - very nice touch for a recipe challenge.  They look very good, too!  (I discovered something called McCormicks Roast Rub, which is a whole lot easier given that I don''t cook, don''t have a mortar and pestle, and would completely forget I had ribs in bags waiting to be cooked after I rubbed them... Anyway, the pre-produced rub probably isn''t nearly as good but works pretty well on tri-tip!)', '2008-07-27 17:32:04.000000', NULL, 0),
(4846761, 698689, 30982, '<td valign="top">I''m not really much of a food person, but I saw this one and it made me hungry.  I definitely don''t cook, but I MAY have to try this.  Looks and sounds awesome!  I think this shot was underrated by the way - I can easily see this in a cookbook with this recipe.  I really like how you captured the flame so well, too.  Great job!</td>', 'I''m not really much of a food person, but I saw this one and it made me hungry.  I definitely don''t cook, but I MAY have to try this.  Looks and sounds awesome!  I think this shot was underrated by the way - I can easily see this in a cookbook with this recipe.  I really like how you captured the flame so well, too.  Great job!', '2008-07-27 17:33:47.000000', NULL, 0),
(4846762, 698256, 30982, '<td valign="top">This was one of those I lingered on in voting - I really like the way you lit it.  Adds so much more atmosphere than the usual set-up shots.  (And don''t tell anyone, but I love to eat the batter...)</td>', 'This was one of those I lingered on in voting - I really like the way you lit it.  Adds so much more atmosphere than the usual set-up shots.  (And don''t tell anyone, but I love to eat the batter...)', '2008-07-27 17:36:00.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4846765, 699607, 30982, '<td valign="top">Really?  Mashed potato mix?  I''d never have thunk it!  And yeah, looks very not good for you, but kids are pretty darn resilient and every now and then a good deep-fat fried bit of chicken is just good for the soul.</td>', 'Really?  Mashed potato mix?  I''d never have thunk it!  And yeah, looks very not good for you, but kids are pretty darn resilient and every now and then a good deep-fat fried bit of chicken is just good for the soul.', '2008-07-27 17:37:56.000000', NULL, 0),
